        var destination = locations[locations.length - 1];
        var waypoints = locations.slice(1, -1);
        var googleMapsUrl = "https://www.google.com/maps/dir/?api=1&origin=" + origin.lat + "," + origin.lng + "&destination=" + destination.lat + "," + destination.lng + "&travelmode=driving";
        if (waypoints.length > 0) {
            var waypointsStr = waypoints.map(function (wp) { return wp.lat + "," + wp.lng; }).join('|');
            googleMapsUrl += "&waypoints=" + waypointsStr;
        }
        window.open(googleMapsUrl, '_blank');
