module.exports = "<div class=\"edit-modal attendance-modal-v2\">\r\n    <form validate #update_basic=\"ngForm\" name=\"update_basic\"\r\n        (ngSubmit)=\"update_basic.valid && changeStatus(modelData.attendance_status)\">\r\n\r\n        <!-- Modal Header -->\r\n        <div class=\"modal-header-v2\">\r\n            <div class=\"header-icon\">\r\n                <i class=\"material-icons\">fingerprint</i>\r\n            </div>\r\n            <div class=\"header-text\">\r\n                <h2>Update Attendance</h2>\r\n                <p class=\"subtitle\">Mark attendance status for the employee</p>\r\n            </div>\r\n            <button type=\"button\" mat-icon-button class=\"close-btn\" [mat-dialog-close]=\"false\">\r\n                <i class=\"material-icons\">close</i>\r\n            </button>\r\n        </div>\r\n\r\n        <div mat-dialog-content class=\"modal-body-v2\">\r\n            <div class=\"cs-form\">\r\n                <div class=\"row\">\r\n\r\n                    <!-- Attendance Status -->\r\n                    <div class=\"col s12\">\r\n                        <div class=\"field-group\">\r\n                            <mat-form-field class=\"cs-input full-width\" appearance=\"outline\">\r\n                                <mat-label>Attendance Status</mat-label>\r\n                                <mat-select name=\"attendance_status\" placeholder=\"\" #attendance_status=\"ngModel\"\r\n                                    [(ngModel)]=\"modelData.attendance_status\" required>\r\n                                    <mat-option value=\"Leave\">\r\n                                        <i class=\"material-icons option-icon\">event_busy</i> Leave\r\n                                    </mat-option>\r\n                                    <mat-option *ngIf=\"leaveType!='Leave'\" value=\"mark_attendance\">\r\n                                        <i class=\"material-icons option-icon\">check_circle</i> Mark Attendance\r\n                                    </mat-option>\r\n                                    <mat-option *ngIf=\"leaveType=='Leave'\" value=\"Absent\">\r\n                                        <i class=\"material-icons option-icon\">cancel</i> Mark Absent\r\n                                    </mat-option>\r\n                                </mat-select>\r\n                            </mat-form-field>\r\n                            <div class=\"field-error\" *ngIf=\"modelData.status || update_basic.submitted\">\r\n                                <p *ngIf=\"attendance_status.errors?.required\">\r\n                                    <i class=\"material-icons\">error_outline</i> This field is required\r\n                                </p>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Leave Type -->\r\n                    <div class=\"col s12\" *ngIf=\"modelData.attendance_status=='Leave'\">\r\n                        <div class=\"field-group\">\r\n                            <mat-form-field appearance=\"outline\" class=\"full-width\"\r\n                                [ngClass]=\"{'has-error' : leave_type.invalid }\">\r\n                                <mat-label>Leave Type</mat-label>\r\n                                <mat-select name=\"leave_type\" #leave_type=\"ngModel\" [(ngModel)]=\"modelData.leave_type\"\r\n                                    required>\r\n                                    <mat-option color=\"accent\" value=\"Full Day\">Full Day</mat-option>\r\n                                    <mat-option color=\"accent\" value=\"Half Day\">Half Day</mat-option>\r\n                                    <mat-option color=\"accent\" value=\"Short Leave\">Short Leave</mat-option>\r\n                                </mat-select>\r\n                            </mat-form-field>\r\n                            <div class=\"field-error\" *ngIf=\"update_basic.submitted && leave_type?.invalid\">\r\n                                <i class=\"material-icons\">error_outline</i> This field is required\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Time Section -->\r\n                    <div class=\"col s12\" *ngIf=\"modelData.attendance_status=='mark_attendance'\">\r\n                        <div class=\"time-section\">\r\n                            <div class=\"time-row\">\r\n                                <div class=\"time-block\">\r\n                                    <label class=\"section-label\">\r\n                                        <i class=\"material-icons\">schedule</i> Start Time\r\n                                    </label>\r\n                                    <input type=\"time\" name=\"start_time\" #start_time=\"ngModel\"\r\n                                        [(ngModel)]=\"modelData.start_time\" class=\"time-input-v2\" required>\r\n                                    <div class=\"field-error\" *ngIf=\"update_basic.submitted && start_time?.invalid\">\r\n                                        <i class=\"material-icons\">error_outline</i> Required\r\n                                    </div>\r\n                                </div>\r\n                                <div class=\"time-divider\">\r\n                                    <i class=\"material-icons\">arrow_forward</i>\r\n                                </div>\r\n                                <div class=\"time-block\">\r\n                                    <label class=\"section-label\">\r\n                                        <i class=\"material-icons\">schedule</i> Stop Time\r\n                                    </label>\r\n                                    <input type=\"time\" name=\"stop_time\" #stop_time=\"ngModel\"\r\n                                        [(ngModel)]=\"modelData.stop_time\" class=\"time-input-v2\">\r\n                                    <div class=\"field-error\" *ngIf=\"update_basic.submitted && stop_time?.invalid\">\r\n                                        <i class=\"material-icons\">error_outline</i> Required\r\n                                    </div>\r\n                                </div>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Upload Image -->\r\n                    <div class=\"col s12\" *ngIf=\"modelData.attendance_status=='mark_attendance'\">\r\n                        <label class=\"section-label\">\r\n                            <i class=\"material-icons\">photo_camera</i> Upload Image\r\n                        </label>\r\n                        <div class=\"upload-area-v2\">\r\n                            <input type=\"file\" accept=\"image/*\" (change)=\"onFileChange($event)\" #fileInput\r\n                                style=\"display: none;\">\r\n                            <div *ngIf=\"!imagePreview\" class=\"upload-placeholder\" (click)=\"fileInput.click()\">\r\n                                <div class=\"upload-icon-wrapper\">\r\n                                    <i class=\"material-icons\">cloud_upload</i>\r\n                                </div>\r\n                                <p class=\"upload-text\">Click to upload image</p>\r\n                                <span class=\"upload-hint\">JPG, PNG up to 5MB</span>\r\n                            </div>\r\n                            <div *ngIf=\"imagePreview\" class=\"image-preview-v2\">\r\n                                <img [src]=\"imagePreview\" class=\"preview-img-v2\">\r\n                                <button type=\"button\" class=\"remove-img-btn\" (click)=\"removeImage()\">\r\n                                    <i class=\"material-icons\">delete</i>\r\n                                </button>\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Working Type -->\r\n                    <div class=\"col s12\" *ngIf=\"modelData.attendance_status=='mark_attendance'\">\r\n                        <label class=\"section-label\">\r\n                            <i class=\"material-icons\">commute</i> Working Type\r\n                        </label>\r\n                        <div class=\"working-type-grid\">\r\n                            <mat-radio-group name=\"working_type\" [(ngModel)]=\"modelData.working_type\" required>\r\n                                <div class=\"type-card\" [class.selected]=\"modelData.working_type === 'Own Bike'\">\r\n                                    <mat-radio-button value=\"Own Bike\">\r\n                                        <i class=\"material-icons type-icon\">two_wheeler</i>\r\n                                        <span>Own Bike</span>\r\n                                    </mat-radio-button>\r\n                                </div>\r\n                                <div class=\"type-card\" [class.selected]=\"modelData.working_type === 'Own Car'\">\r\n                                    <mat-radio-button value=\"Own Car\">\r\n                                        <i class=\"material-icons type-icon\">directions_car</i>\r\n                                        <span>Own Car</span>\r\n                                    </mat-radio-button>\r\n                                </div>\r\n                                <div class=\"type-card\" [class.selected]=\"modelData.working_type === 'Public Transport'\">\r\n                                    <mat-radio-button value=\"Public Transport\">\r\n                                        <i class=\"material-icons type-icon\">directions_bus</i>\r\n                                        <span>Public Transport</span>\r\n                                    </mat-radio-button>\r\n                                </div>\r\n                                <div class=\"type-card\"\r\n                                    [class.selected]=\"modelData.working_type === 'Colleague Vehicle'\">\r\n                                    <mat-radio-button value=\"Colleague Vehicle\">\r\n                                        <i class=\"material-icons type-icon\">airport_shuttle</i>\r\n                                        <span>Colleague's Vehicle</span>\r\n                                    </mat-radio-button>\r\n                                </div>\r\n                            </mat-radio-group>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Location -->\r\n                    <div class=\"col s12\" *ngIf=\"modelData.attendance_status=='mark_attendance'\">\r\n                        <label class=\"section-label\">\r\n                            <i class=\"material-icons\">location_on</i> Location\r\n                        </label>\r\n                        <div class=\"location-row\">\r\n                            <mat-form-field class=\"cs-input\" appearance=\"outline\">\r\n                                <mat-label>Latitude</mat-label>\r\n                                <input matInput type=\"text\" name=\"start_lat\" #start_lat=\"ngModel\"\r\n                                    [(ngModel)]=\"modelData.start_lat\">\r\n                            </mat-form-field>\r\n                            <mat-form-field class=\"cs-input\" appearance=\"outline\">\r\n                                <mat-label>Longitude</mat-label>\r\n                                <input matInput type=\"text\" name=\"start_lng\" #start_lng=\"ngModel\"\r\n                                    [(ngModel)]=\"modelData.start_lng\">\r\n                            </mat-form-field>\r\n                        </div>\r\n                    </div>\r\n\r\n                    <!-- Remark -->\r\n                    <div class=\"col s12\">\r\n                        <div class=\"field-group\">\r\n                            <mat-form-field class=\"cs-input full-width\" appearance=\"outline\"\r\n                                [ngClass]=\"{'has-error' : remarks.invalid }\">\r\n                                <mat-label>Remark</mat-label>\r\n                                <textarea matInput placeholder=\"Write your remark here...\" name=\"remarks\"\r\n                                    #remarks=\"ngModel\" [(ngModel)]=\"modelData.remarks\" required rows=\"3\"></textarea>\r\n                            </mat-form-field>\r\n                            <div class=\"field-error\" *ngIf=\"update_basic.submitted && remarks?.invalid\">\r\n                                <i class=\"material-icons\">error_outline</i> This field is required\r\n                            </div>\r\n                        </div>\r\n                    </div>\r\n\r\n                </div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- Footer Actions -->\r\n        <div class=\"modal-footer-v2\">\r\n            <button type=\"button\" mat-stroked-button class=\"cancel-btn-v2\" [mat-dialog-close]=\"false\">\r\n                <i class=\"material-icons\">close</i> Cancel\r\n            </button>\r\n            <button mat-raised-button type=\"submit\" class=\"submit-btn-v2\" [disabled]=\"savingFlag == true\"\r\n                [ngClass]=\"{'loading': savingFlag == true}\">\r\n                <i class=\"material-icons\" *ngIf=\"savingFlag != true\">check_circle</i>\r\n                <span *ngIf=\"savingFlag != true\">Update</span>\r\n                <span *ngIf=\"savingFlag == true\" class=\"saving-spinner\">\r\n                    <i class=\"material-icons spin\">autorenew</i> Saving...\r\n                </span>\r\n            </button>\r\n        </div>\r\n    </form>\r\n</div>"

