    TrackerComponent.prototype.AttendanceSummary = function () {
        var _this = this;
        var paylod = { 'start_date': this.filter.date, 'user_id': this.payload.user_id };
        this.service.post_rqst(paylod, "Location/attendanceSummary").subscribe((function (result) {
            if (result['statusCode'] == 200) {
                _this.Attendancedata = result['data'];
                _this.Checkincount = result['checkinCount'];
                _this.totalDistanceSummary = result['total_distance'];
                if (_this.Attendancedata.length == 0) {
                    _this.datanotfound = true;
                }
                else {
                    _this.datanotfound = false;
                }
            }
            else {
                _this.toast.errorToastr(result['statusMsg']);
            }
        }));
    };
    TrackerComponent.prototype.ngOnInit = function () {
        var _this = this;
        if (this.dataToReceive != undefined) {
            this.padding0 = this.dataToReceive.padding0;
            this.payload = { 'start_date': this.dataToReceive.start_date, 'user_id': this.dataToReceive.user_id };
            this.getLatesRoute();
            this.getDetails();
        }
        else {
            this.router.params.subscribe(function (params) {
                _this.payload = _this.router.queryParams['_value'];
                if (_this.payload) {
                    _this.selectedDate = _this.filter.date = _this.payload.start_date;
                    _this.getLatesRoute();
                    _this.getDetails();
                }
            });
        }
    };
    TrackerComponent.prototype.getDetails = function () {
        var _this = this;
        var header;
        if (this.filter.date) {
            header = { 'start_date': this.filter.date, 'user_id': this.payload.user_id };
        }
        else {
            header = this.payload;
        }
        this.service.post_rqst(header, "Location/getLatestGeoLocation")
            .subscribe((function (result) {
            if (result['statusCode'] == 200) {
                _this.empData = result['user_data'];
                _this.latestLocation = result['latest_location'];
                _this.pathCoords = result['data'];
            }
            else {
                _this.toast.errorToastr(result['statusMsg']);
            }
        }));
    };
    TrackerComponent.prototype.getLatesRoute = function () {
        var _this = this;
        this.skLoading = true;
        this.isLoading = true;
        console.log("this is called");
        var header;
        if (this.filter.date) {
            header = { 'start_date': this.filter.date, 'user_id': this.payload.user_id };
        }
        else {
            header = this.payload;
        }
        this.service.post_rqst(header, "Location/getLatestRoute")
            .subscribe((function (result) {
            if (result['statusCode'] == 200) {
                _this.defaultCoordinates = { lat: result['latest_location']['lat'], lng: result['latest_location']['lng'] };
                _this.location = result['data'];
                _this.filteredLocations = _this.filterConsecutiveCheckins(_this.location);
                _this.checkin_data = result['checkin_summary'];
                console.log(_this.checkin_data, 'this.checkin_data');
                _this.LocationDistance = result['distance'];
                _this.location_accuracy = result['location_accuracy'];
                _this.locationMarkers = _this.location;
                _this.skLoading = false;
                if (_this.locationMarkers.length && _this.tabType != 'Battery' && _this.tabType != 'Attendance Summary') {
                    if (_this.mapPlaybackControl) {
                        _this.mapPlaybackControl = '';
                    }
                    setTimeout(function () {
                        _this.initializeMap();
                    }, 3000);
                    setTimeout(function () {
                        _this.isLoading = false;
                    }, 4000);
                }
            }
            else {
                _this.toast.errorToastr(result['statusMsg']);
                _this.isLoading = false;
                _this.skLoading = false;
            }
        }));
    };
