        console.log('Logging Action for User:', userId, this.selectedActionUser);
        var userName = this.selectedActionUser.created_by_name || this.selectedActionUser.name;
        var contextStr = '';
        if (this.selectedActionReason === 'Checkout Reminder') {
            contextStr = "Visited: " + this.selectedActionUser.dr_name + " (" + this.selectedActionUser.dr_type_name + ") | Working Time: [" + this.selectedActionUser.Total_Working_Time + "]";
        }
