    DashboardComponent.prototype.otGetTotal = function () {
        if (!this.orderTrendData.length)
            return 0;
        var field = this.orderTrendFilter.metric_type === 'tonnage' ? 'weight' : 'qty';
        return this.orderTrendData.reduce(function (sum, d) { return sum + (Number(d[field]) || 0); }, 0);
    };
    DashboardComponent.prototype.otGetPeak = function () {
        if (!this.orderTrendData.length)
            return null;
        var field = this.orderTrendFilter.metric_type === 'tonnage' ? 'weight' : 'qty';
        return this.orderTrendData.reduce(function (best, d) {
            return (Number(d[field]) > Number(best[field]) ? d : best);
        }, this.orderTrendData[0]);
    };
    DashboardComponent.prototype.otGetTrend = function () {
        if (this.orderTrendData.length < 2)
            return '—';
        var field = this.orderTrendFilter.metric_type === 'tonnage' ? 'weight' : 'qty';
        var last = Number(this.orderTrendData[this.orderTrendData.length - 1][field]) || 0;
        var prev = Number(this.orderTrendData[this.orderTrendData.length - 2][field]) || 0;
        if (last > prev)
            return '↑ Up';
        if (last < prev)
            return '↓ Down';
        return '→ Flat';
    };
