    AddDistributionComponent.prototype.verifyPan = function () {
        var _this = this;
        if (!this.data.pan_no) {
            this.toast.errorToastr('Enter Valid PAN No.');
            return;
        }
        if (!this.data.adhar_no) {
            this.toast.errorToastr('Enter Aadhaar Number First');
            return;
        }
        this.data.verification_id = String(Math.floor(100000 + Math.random() * 900000));
        this.verifyFlag = true;
        this.service.post_rqst({
            verification_id: this.data.verification_id,
            pan: this.data.pan_no,
            name: this.data.pan_name,
            dob: this.data.dob,
            id: this.pageType == 'edit' ? this.params_type : '',
        }, "Influencer/pan_verification").subscribe(function (result) {
            _this.verifyFlag = false;
            if (result["statusCode"] == 200) {
                var res = result['case'] &&
                    result['case'].response
                    ? result['case'].response
                    : null;
                if (!res) {
                    _this.toast.errorToastr("Invalid API response");
                    return;
                }
                // -------------------------------
                // 1️⃣ Aadhaar Mask Checking First
                // -------------------------------
                var masked = res.masked_aadhaar_number;
                var aadhaar_linked = res.aadhaar_linked;
                _this.data.masked_aadhaar_number = res.masked_aadhaar_number;
                var userAadhar = _this.data.adhar_no;
                console.log(userAadhar, 'userAadhar');
                var last4 = userAadhar.slice(-2);
                console.log(last4, 'last4');
                if (aadhaar_linked == false && !masked) {
                    _this.toast.errorToastr("Pan Is Not Linked with Aadhar");
                    // this.data.adhar_verified = true;
                    _this.data.aadhaar_linked = res.aadhaar_linked;
                    _this.data.cashfree_pan_status = "INVALID";
                    return;
                }
                console.log(masked);
                console.log(masked.endsWith(last4));
                if (!masked || !masked.endsWith(last4)) {
                    _this.toast.errorToastr("Aadhaar number does not match PAN records.");
                    _this.data.adhar_verified = true;
                    _this.data.cashfree_pan_status = "INVALID";
                    return;
                }
                // Aadhaar matched = success
                // this.data.adhar_verified = true;
                // -------------------------------
                // 2️⃣ Now check PAN status
                // -------------------------------
                if (res.status === "VALID") {
                    _this.toast.successToastr("PAN & Aadhaar verified successfully!");
                    _this.data.cashfree_pan_status = res.status;
                    _this.data.cashfree_aadhar_status = res.status;
                    _this.data.aadhaar_linked = res.aadhaar_linked;
                    _this.data.pan_name = res.name_pan_card;
                    _this.data.masked_aadhaar_number = res.masked_aadhaar_number;
                }
                else {
                    _this.data.cashfree_pan_status = "INVALID";
                    _this.toast.errorToastr(res.message || "PAN Verification Failed");
                }
            }
            else if (result["statusCode"] == 400) {
                _this.toast.errorToastr(result["case"]);
                _this.verifyFlag = false;
            }
            else {
                _this.toast.errorToastr(result["statusMsg"]);
                _this.verifyFlag = false;
            }
        });
    };
