module.exports = "<div class=\"doc-preview-modal\">\r\n\r\n    <div class=\"dp-header\">\r\n        <h2>Document Preview</h2>\r\n        <button mat-icon-button (click)=\"close()\"><i class=\"material-icons\">close</i></button>\r\n    </div>\r\n\r\n    <div class=\"dp-loader\" *ngIf=\"loader\">\r\n        <i class=\"material-icons spin\">autorenew</i> Loading documents...\r\n    </div>\r\n\r\n    <div class=\"dp-body\" *ngIf=\"!loader\">\r\n\r\n        <!-- details page -->\r\n        <div class=\"dp-details\">\r\n            <h3>Document Details</h3>\r\n            <div class=\"dp-grid\">\r\n                <div><span>Name</span><p>{{details.name || '---'}}</p></div>\r\n                <div><span>PAN Name</span><p>{{details.pan_name || '---'}}</p></div>\r\n                <div><span>PAN Number</span><p>{{details.pan_no || '---'}}</p></div>\r\n                <div><span>Aadhaar Number</span><p>{{details.adhar_no || '---'}}</p></div>\r\n                <div><span>Bank Name</span><p>{{details.bank_name || '---'}}</p></div>\r\n                <div><span>Account Number</span><p>{{details.account_no || '---'}}</p></div>\r\n                <div><span>IFSC Code</span><p>{{details.ifsc_code || '---'}}</p></div>\r\n                <div><span>Account Holder</span><p>{{details.account_holder_name || '---'}}</p></div>\r\n            </div>\r\n        </div>\r\n\r\n        <!-- one preview \"page\" per document -->\r\n        <div class=\"dp-page\" *ngFor=\"let doc of docs\">\r\n            <div class=\"dp-page-head\">\r\n                <h4>\r\n                    {{doc.label}}\r\n                    <span class=\"edited-tag\" *ngIf=\"doc.changed\">edited</span>\r\n                    <span class=\"custom-tag\" *ngIf=\"doc.custom\">added</span>\r\n                </h4>\r\n                <div class=\"dp-page-actions\">\r\n                    <button mat-stroked-button color=\"primary\" (click)=\"openEditor(doc)\">\r\n                        <i class=\"material-icons\">edit</i> Edit\r\n                    </button>\r\n                    <button mat-icon-button color=\"warn\" *ngIf=\"doc.custom\" matTooltip=\"Remove page\"\r\n                        (click)=\"removeDoc(doc)\">\r\n                        <i class=\"material-icons\">delete</i>\r\n                    </button>\r\n                </div>\r\n            </div>\r\n            <div class=\"dp-img-wrap\">\r\n                <img [src]=\"doc.edited\" />\r\n            </div>\r\n        </div>\r\n\r\n        <div class=\"dp-empty\" *ngIf=\"docs.length === 0\">\r\n            No documents uploaded for this profile.\r\n        </div>\r\n\r\n        <!-- add a new custom document/page -->\r\n        <button class=\"dp-add-card\" (click)=\"openAddPage()\">\r\n            <i class=\"material-icons\">add_photo_alternate</i>\r\n            <span>Add Document / Page</span>\r\n        </button>\r\n    </div>\r\n\r\n    <div class=\"dp-footer\" *ngIf=\"!loader\">\r\n        <button mat-raised-button (click)=\"close()\">Close</button>\r\n        <button mat-raised-button color=\"accent\" [disabled]=\"saving\" (click)=\"saveToServer()\">\r\n            <i class=\"material-icons\">cloud_upload</i> {{saving ? 'Saving...' : 'Save to Profile'}}\r\n        </button>\r\n        <button mat-raised-button color=\"primary\" [disabled]=\"docs.length === 0\" (click)=\"downloadWord()\">\r\n            <i class=\"material-icons\">description</i> Download Word\r\n        </button>\r\n    </div>\r\n\r\n    <!-- image editor overlay -->\r\n    <div class=\"dp-editor-overlay\" *ngIf=\"editing\">\r\n        <div class=\"dp-editor\">\r\n            <div class=\"dp-editor-head\">\r\n                <h3>Edit — {{editing.label}}</h3>\r\n                <button mat-icon-button (click)=\"cancelEdit()\"><i class=\"material-icons\">close</i></button>\r\n            </div>\r\n\r\n            <div class=\"doc-cropper\">\r\n                <img #cropperImg [src]=\"editing.edited\" />\r\n            </div>\r\n\r\n            <div class=\"dp-tools\">\r\n                <button mat-icon-button matTooltip=\"Rotate left\" (click)=\"rotate(-90)\">\r\n                    <i class=\"material-icons\">rotate_left</i>\r\n                </button>\r\n                <button mat-icon-button matTooltip=\"Rotate right\" (click)=\"rotate(90)\">\r\n                    <i class=\"material-icons\">rotate_right</i>\r\n                </button>\r\n                <button mat-icon-button matTooltip=\"Zoom in\" (click)=\"zoom(0.1)\">\r\n                    <i class=\"material-icons\">zoom_in</i>\r\n                </button>\r\n                <button mat-icon-button matTooltip=\"Zoom out\" (click)=\"zoom(-0.1)\">\r\n                    <i class=\"material-icons\">zoom_out</i>\r\n                </button>\r\n\r\n                <div class=\"slider\">\r\n                    <label>Brightness</label>\r\n                    <input type=\"range\" min=\"0\" max=\"200\" [(ngModel)]=\"brightness\" (input)=\"applyFilterPreview()\" />\r\n                    <span>{{brightness}}%</span>\r\n                </div>\r\n                <div class=\"slider\">\r\n                    <label>Contrast</label>\r\n                    <input type=\"range\" min=\"0\" max=\"200\" [(ngModel)]=\"contrast\" (input)=\"applyFilterPreview()\" />\r\n                    <span>{{contrast}}%</span>\r\n                </div>\r\n\r\n                <button mat-button (click)=\"resetEditor()\">\r\n                    <i class=\"material-icons\">restart_alt</i> Reset\r\n                </button>\r\n            </div>\r\n\r\n            <div class=\"dp-editor-foot\">\r\n                <button mat-raised-button (click)=\"cancelEdit()\">Cancel</button>\r\n                <button mat-raised-button color=\"primary\" (click)=\"applyEdit()\">Apply</button>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <!-- add new document / page overlay -->\r\n    <div class=\"dp-editor-overlay\" *ngIf=\"adding\">\r\n        <div class=\"dp-editor\">\r\n            <div class=\"dp-editor-head\">\r\n                <h3>Add Document / Page</h3>\r\n                <button mat-icon-button (click)=\"cancelAddPage()\"><i class=\"material-icons\">close</i></button>\r\n            </div>\r\n\r\n            <div class=\"dp-add-body\">\r\n                <label class=\"dp-add-label\">\r\n                    <span>Page Heading</span>\r\n                    <input type=\"text\" [(ngModel)]=\"newLabel\" placeholder=\"e.g. GST Certificate, Shop Photo\" />\r\n                </label>\r\n\r\n                <!-- paste zone (Ctrl+V) + file upload, like attendance -->\r\n                <div class=\"dp-paste-zone\" tabindex=\"0\" (paste)=\"onAddPaste($event)\">\r\n                    <ng-container *ngIf=\"!newImage\">\r\n                        <i class=\"material-icons\">content_paste</i>\r\n                        <p>Click here and press <b>Ctrl + V</b> to paste an image</p>\r\n                        <p class=\"or\">— or —</p>\r\n                        <label class=\"dp-upload-btn\">\r\n                            <i class=\"material-icons\">upload</i> Upload Image\r\n                            <input type=\"file\" accept=\"image/*\" (change)=\"onAddFile($event)\" hidden />\r\n                        </label>\r\n                    </ng-container>\r\n                    <div class=\"dp-add-preview\" *ngIf=\"newImage\">\r\n                        <img [src]=\"newImage\" />\r\n                        <button mat-button color=\"warn\" (click)=\"newImage = ''\">\r\n                            <i class=\"material-icons\">delete</i> Remove\r\n                        </button>\r\n                    </div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"dp-editor-foot\">\r\n                <button mat-raised-button (click)=\"cancelAddPage()\">Cancel</button>\r\n                <button mat-raised-button color=\"primary\" [disabled]=\"!newImage\" (click)=\"confirmAddPage()\">\r\n                    Add Page\r\n                </button>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n</div>\r\n"

