    // Helper function to calculate duration between two datetime strings
    MapComponent.prototype.calculateDuration = function (start, end) {
        var startTime = moment__WEBPACK_IMPORTED_MODULE_6__(start);
        var endTime = moment__WEBPACK_IMPORTED_MODULE_6__(end);
        var duration = moment__WEBPACK_IMPORTED_MODULE_6__["duration"](endTime.diff(startTime));
        var hours = Math.floor(duration.asHours());
        var minutes = duration.minutes();
        if (hours > 0) {
            return hours + "h " + minutes + "m";
        }
        return minutes + " minutes";
    };
    // Helper function to calculate duration from time strings like "10:58:43"
    MapComponent.prototype.calculateFaceTime = function (startTime, endTime) {
        if (!startTime || !endTime) {
            return '--';
        }
        // Parse time strings (HH:mm:ss format)
        var startParts = startTime.split(':').map(Number);
        var endParts = endTime.split(':').map(Number);
        if (startParts.length < 2 || endParts.length < 2) {
            return '--';
        }
        // Convert to seconds
        var startSeconds = (startParts[0] * 3600) + (startParts[1] * 60) + (startParts[2] || 0);
        var endSeconds = (endParts[0] * 3600) + (endParts[1] * 60) + (endParts[2] || 0);
        // Calculate difference
        var diffSeconds = endSeconds - startSeconds;
        // Handle case where end time might be next day (though unlikely for face time)
        if (diffSeconds < 0) {
            diffSeconds += 24 * 3600;
        }
        var hours = Math.floor(diffSeconds / 3600);
        var minutes = Math.floor((diffSeconds % 3600) / 60);
        var seconds = diffSeconds % 60;
        if (hours > 0) {
            return hours + "h " + minutes + "m";
        }
        else if (minutes > 0) {
            return minutes + "m " + seconds + "s";
        }
        return seconds + "s";
    };
    // Helper function to format time string "10:58:43" to "10:58 AM" format
    MapComponent.prototype.formatTimeToAmPm = function (timeString) {
        if (!timeString) {
            return '--';
        }
        var parts = timeString.split(':').map(Number);
        if (parts.length < 2) {
            return timeString;
        }
        var hours = parts[0];
        var minutes = parts[1];
        var ampm = hours >= 12 ? 'PM' : 'AM';
        hours = hours % 12;
        hours = hours ? hours : 12; // 0 should be 12
        return hours + ":" + minutes.toString().padStart(2, '0') + " " + ampm;
    };
    // Helper function to format seconds to readable time
    MapComponent.prototype.formatSeconds = function (seconds) {
        var hours = Math.floor(seconds / 3600);
        var minutes = Math.floor((seconds % 3600) / 60);
        if (hours > 0) {
            return hours + "h " + minutes + "m";
        }
        return minutes + " minutes";
    };
