    MapComponent.prototype.buildCalendarWeeks = function () {
        if (!this.kmCalendarData || !this.kmCalendarData.calendar_data) {
            this.calendarWeeks = [];
            return;
        }
        var calendarData = this.kmCalendarData.calendar_data;
        // Get the first day of the month
        var firstDay = new Date(this.selectedKmYear, this.selectedKmMonth - 1, 1);
        var startDayOfWeek = firstDay.getDay(); // 0 = Sunday, 1 = Monday, etc.
        // Create a map of dates to data
        var dateMap = new Map();
        calendarData.forEach(function (day) {
            dateMap.set(day.date, day);
        });
        // Build weeks array
        this.calendarWeeks = [];
        var currentWeek = [];
        // Add empty cells for days before the first day of month
        for (var i = 0; i < startDayOfWeek; i++) {
            currentWeek.push(null);
        }
        // Get number of days in month
        var daysInMonth = new Date(this.selectedKmYear, this.selectedKmMonth, 0).getDate();
        for (var day = 1; day <= daysInMonth; day++) {
            var dateStr = this.selectedKmYear + "-" + String(this.selectedKmMonth).padStart(2, '0') + "-" + String(day).padStart(2, '0');
            var dayData = dateMap.get(dateStr) || {
                date: dateStr,
                day: new Date(dateStr).toLocaleDateString('en-US', { weekday: 'long' }),
                km_per_day: null,
                has_attendance: false
            };
            currentWeek.push(dayData);
            if (currentWeek.length === 7) {
                this.calendarWeeks.push(currentWeek);
                currentWeek = [];
            }
        }
        // Fill remaining days of last week with empty cells
        if (currentWeek.length > 0) {
            while (currentWeek.length < 7) {
                currentWeek.push(null);
            }
            this.calendarWeeks.push(currentWeek);
        }
    };
