    RedeemStatusModalComponent.prototype.onStatusFileChange = function (event) {
        var _this = this;
        var file = event.target.files && event.target.files[0];
        if (!file) {
            return;
        }
        var isPdf = file.type === 'application/pdf' || /\.pdf$/i.test(file.name);
        var isImage = (file.type || '').indexOf('image/') === 0;
        if (!isPdf && !isImage) {
            this.toast.errorToastr('Only image or PDF files are allowed');
            return;
        }
        this.status_file_type = isPdf ? 'pdf' : 'image';
        this.status_file_name = file.name;
        var reader = new FileReader();
        reader.onload = function (e) {
            _this.status_file_data = e.target.result; // base64 data URI
        };
        reader.readAsDataURL(file);
    };
