    UploadFileModalComponent.prototype.otherSample = function (type) {
        var _this = this;
        var CsvName;
        if (this.network_type == '1') {
            CsvName = 'Distributor';
        }
        else if (this.network_type == '3') {
            CsvName = 'Retailer';
        }
        else {
            CsvName = 'DirectDealer';
        }
        this.excel_loader = true;
        if (type == 'geo_location') {
            this.serve.post_rqst({ 'type': this.network_type, 'type_name': CsvName }, "CustomerNetwork/generateExcelForLatLngUpdate").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    _this.excel_loader = false;
                    document.location.replace(_this.uploadurl + 'update_sample_file/' + CsvName + 'geoLocationUpdate.csv');
                }
            }, function (err) {
                _this.excel_loader = false;
            });
        }
        else if (type == 'credit_limit') {
            this.serve.post_rqst({ 'type': this.network_type, 'type_name': CsvName }, "CustomerNetwork/generateExcelForCreditLimitUpdate").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    _this.excel_loader = false;
                    document.location.replace(_this.uploadurl + 'update_sample_file/' + CsvName + 'CreditLimitUpdate.csv');
                }
            }, function (err) {
                _this.excel_loader = false;
            });
        }
        else {
            this.serve.post_rqst({ 'type': this.network_type, 'type_name': CsvName, 'filter': this.filter_data }, "CustomerNetwork/generateExcelForUserBulkAssigningDr").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    _this.excel_loader = false;
                    document.location.replace(_this.uploadurl + 'update_sample_file/' + result['response']);
                }
                else {
                    _this.toast.errorToastr(result['statusMsg']);
                }
            }, function (err) {
                _this.excel_loader = false;
            });
        }
    };
    UploadFileModalComponent.prototype.upload_distribution_excel = function (type) {
        var _this = this;
        this.dialogRef.disableClose = true;
        this.formData.append('category', this.file, this.file.name);
        this.formData.append('created_by_id', this.userId);
        this.formData.append('created_by_name', this.userName);
        this.formData.append('type', this.type);
        this.excel_loader = true;
        var header;
        // if ((this.network_type == 1 || this.network_type == 7) && type == 'credit_limit') {
        //   header = this.serve.FileData(this.formData, 'CustomerNetwork/updateCreditLimit')
        // }
        // else if ((this.network_type == 1 || this.network_type == 3 || this.network_type == 7) && type == 'geo_location') {
        //   header = this.serve.FileData(this.formData, 'CustomerNetwork/updateGeoLocation')
        // }
        // else if (type == 'update') {
        //   header = this.serve.FileData(this.formData, 'CustomerNetwork/updateCustomerBasicDetails')
        // }
        // else if (this.network_type == 3 && type == 'insert') {
        //   header = this.serve.FileData(this.formData, 'CustomerNetwork/importRetailerExcel')
        // }
        if ((this.network_type == 1 || this.network_type == 7) && type == 'insert') {
            header = this.serve.FileData(this.formData, 'CustomerNetwork/importDistributorExcel');
        }
        else if ((this.network_type == 3) && type == 'insert') {
            header = this.serve.FileData(this.formData, 'CustomerNetwork/importRetailerExcel');
        }
        else if ((this.network_type == 14) && type == 'insert') {
            header = this.serve.FileData(this.formData, 'CustomerNetwork/importBuilderExcel');
        }
        else if ((this.network_type == 8 || this.network_type == 13) && type == 'insert') {
            header = this.serve.FileData(this.formData, 'CustomerNetwork/importInfluencerExcel');
        }
        else {
            header = this.serve.FileData(this.formData, 'CustomerNetwork/updateBulkUserAssigningDr');
        }
        header.subscribe(function (d) {
            _this.dialogRef.disableClose = false;
            _this.formData = new FormData();
            if (d['statusCode'] == 200) {
                _this.toast.successToastr(d['statusMsg']);
                _this.dialogRef.close(true);
                _this.excel_loader = false;
                _this.serve.dr_list();
                return;
            }
            else {
                _this.excel_loader = false;
                _this.uploadError = true;
                _this.uploadErrorMsg = d['statusMsg'];
                _this.uploadErrorMsgCount = d['response'];
                _this.excel_loader = false;
            }
        }, function (err) {
            _this.toast.errorToastr('Something went wrong');
            _this.excel_loader = false;
        });
    };
