    UploadFileModalComponent.prototype.targetSample = function () {
        var _this = this;
        if (this.modal_type == 'add new' && this.come_from == 'distributor_target') {
            this.serve.post_rqst({ 'type': this.network_type }, "Target/generateExcelForDistributorTargetUpload").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    document.location.replace(_this.uploadurl + 'sample_file/DistributorTargetUpload.csv');
                }
                else {
                    _this.toast.errorToastr(result['statusMsg']);
                }
            });
        }
        if (this.modal_type == 'update' && this.come_from == 'distributor_target') {
            if (!this.filter.month) {
                this.toast.errorToastr("Please select month!");
                return;
            }
            if (!this.filter.year) {
                this.toast.errorToastr("Please enter year!");
                return;
            }
            if (this.filter.year.length < 4) {
                this.toast.errorToastr("Year is not valid");
                return;
            }
            this.serve.post_rqst({ 'type': this.network_type, 'month': this.filter.month, 'year': this.filter.year }, "Target/generateExcelForDistributorTargetUpdate").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    document.location.replace(_this.uploadurl + 'update_sample_file/DistributorTargetUpdate.csv');
                }
                else {
                    _this.toast.errorToastr(result['statusMsg']);
                }
            });
        }
        if (this.modal_type == 'employee_target' && this.come_from == 'user_visit_target') {
            this.serve.post_rqst({}, "Target/generateExcelForUserTargetUpload").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    document.location.replace(_this.uploadurl + 'sample_file/UserTargetUpload.csv');
                }
                else {
                    _this.toast.errorToastr(result['statusMsg']);
                }
            });
        }
        if (this.modal_type == 'employee_target_projection' && this.come_from == 'user_visit_target') {
            this.serve.post_rqst({}, "Target/generateExcelForprojection_achievement_list").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    document.location.replace(_this.uploadurl + 'sample_file/UserProjectionUpload.csv');
                }
                else {
                    _this.toast.errorToastr(result['statusMsg']);
                }
            });
        }
        if (this.modal_type == 'employee_target_projection_upload' && this.come_from == 'user_visit_target') {
            if (!this.filter.month) {
                return this.toast.errorToastr("Kindly Select Month");
            }
            if (!this.filter.year) {
                return this.toast.errorToastr("Kindly Enter Year");
            }
            this.serve.post_rqst({ 'month': this.filter.month, 'year': this.filter.year }, "Target/generateExcelForProjectionUpdate").subscribe(function (result) {
                if (result['statusCode'] == 200) {
                    _this.excel_loader = false;
                    document.location.replace(_this.uploadurl + 'update_sample_file/BulkUpdateEmployeeTaget.csv');
                }
                else {
                    _this.toast.errorToastr(result['statusMsg']);
                }
            }, function (err) {
                _this.excel_loader = false;
                _this.toast.errorToastr("No data found");
            });
        }
    };
